        redisTemplate.opsForZSet().add(metricKey + ":1m", 
            event.getEventId(), event.getTimestamp().toEpochMilli());
        redisTemplate.expire(metricKey + ":1m", Duration.ofMinutes(2));

        // Update 1-hour window
        redisTemplate.opsForZSet().add(metricKey + ":1h", 
            event.getEventId(), event.getTimestamp().toEpochMilli());
        redisTemplate.expire(metricKey + ":1h", Duration.ofHours(2));

        // Update daily window
        redisTemplate.opsForZSet().add(metricKey + ":1d", 
            event.getEventId(), event.getTimestamp().toEpochMilli());
        redisTemplate.expire(metricKey + ":1d", Duration.ofDays(2));
    }
