    public StatisticalSummary calculateStatistics(List<TimeSeriesPoint> data) {
        // Time-series statistical analysis
        LongSummaryStatistics requestStats = data.stream()
            .mapToLong(TimeSeriesPoint::getRequestCount)
            .summaryStatistics();

        DoubleSummaryStatistics latencyStats = data.stream()
            .mapToDouble(TimeSeriesPoint::getAverageLatency)
            .summaryStatistics();

        double successRate = data.stream()
            .mapToDouble(point -> (double) point.getSuccessfulRequests() / point.getRequestCount())
            .average()
            .orElse(0.0);

        // Peak usage analysis
        PeakUsageAnalysis peakAnalysis = analyzePeakUsage(data);

        // Percentile calculations
        Percentiles percentiles = calculatePercentiles(data);

        return StatisticalSummary.builder()
            .totalRequests(requestStats.getSum())
            .averageRequestsPerMinute(requestStats.getAverage())
            .peakRequestsPerMinute(requestStats.getMax())
            .averageLatency(latencyStats.getAverage())
            .p95Latency(percentiles.getP95Latency())
            .p99Latency(percentiles.getP99Latency())
            .successRate(successRate)
            .peakUsage(peakAnalysis)
            .build();
    }

    @Async
    public CompletableFuture<List<UsagePattern>> detectUsagePatterns(String tenantId, Duration lookbackPeriod) {
        Instant endTime = Instant.now();
        Instant startTime = endTime.minus(lookbackPeriod);

        List<TimeSeriesPoint> data = timeSeriesDB.query(tenantId, startTime, endTime);

        List<UsagePattern> patterns = new ArrayList<>();

        // Daily patterns
        patterns.addAll(detectDailyPatterns(data));

        // Weekly patterns
        patterns.addAll(detectWeeklyPatterns(data));

        // Seasonal patterns
        patterns.addAll(detectSeasonalPatterns(data));

        // Burst patterns
        patterns.addAll(detectBurstPatterns(data));

        // API-specific patterns
        patterns.addAll(detectApiSpecificPatterns(data));

        return CompletableFuture.completedFuture(patterns);
    }

    private List<UsagePattern> detectDailyPatterns(List<TimeSeriesPoint> data) {
        // Group data by hour of day
        Map<Integer, List<TimeSeriesPoint>> hourlyData = data.stream()
            .collect(Collectors.groupingBy(point -> 
                LocalDateTime.ofInstant(point.getTimestamp(), ZoneOffset.UTC).getHour()
            ));

        List<UsagePattern> patterns = new ArrayList<>();

        // Find peak hours
        Map<Integer, Double> hourlyAverages = hourlyData.entrySet().stream()
            .collect(Collectors.toMap(
                Map.Entry::getKey,
                entry -> entry.getValue().stream()
                    .mapToLong(TimeSeriesPoint::getRequestCount)
                    .average()
                    .orElse(0.0)
            ));

        OptionalDouble maxAverage = hourlyAverages.values().stream().mapToDouble(Double::doubleValue).max();
        OptionalDouble minAverage = hourlyAverages.values().stream().mapToDouble(Double::doubleValue).min();

        if (maxAverage.isPresent() && minAverage.isPresent()) {
            double threshold = minAverage.getAsDouble() + (maxAverage.getAsDouble() - minAverage.getAsDouble()) * 0.7;

            List<Integer> peakHours = hourlyAverages.entrySet().stream()
                .filter(entry -> entry.getValue() > threshold)
                .map(Map.Entry::getKey)
                .sorted()
                .collect(Collectors.toList());

            if (!peakHours.isEmpty()) {
                patterns.add(UsagePattern.builder()
                    .type(PatternType.DAILY_PEAK)
                    .description("Daily peak usage hours: " + peakHours)
                    .confidence(calculatePatternConfidence(peakHours, hourlyAverages))
                    .recommendation(generatePeakHourRecommendation(peakHours))
                    .metadata(Map.of(
                        "peak_hours", peakHours,
                        "peak_average", maxAverage.getAsDouble(),
                        "off_peak_average", minAverage.getAsDouble()
                    ))
                    .build());
            }
        }

        return patterns;
    }
}
