                .rule(rule)
                .event(event)
                .historicalData(getHistoricalData(rule, event))
                .currentMetrics(getCurrentMetrics(rule, event))
                .build();

            AlertEvaluationResult result = rule.getCondition().evaluate(context);

            if (result.isTriggered()) {
