            .key(event.getKey())
            .currentEvent(event)
            .historicalWindow(Duration.ofHours(24))
            .build();

        AnomalyDetectionResult result = anomalyDetection.detectAnomaly(request);

        if (result.isAnomalous()) {
            Alert anomalyAlert = Alert.builder()
                .id(UUID.randomUUID().toString())
                .type(AlertType.ANOMALY)
                .severity(result.getSeverity())
                .title("Anomaly Detected: " + result.getAnomalyType())
                .description(result.getDescription())
                .tenantId(event.getTenantId())
                .key(event.getKey())
                .triggeredAt(Instant.now())
                .confidence(result.getConfidence())
                .metadata(result.getMetadata())
                .build();

            notificationService.sendAlert(anomalyAlert);
        }
    }

    public AlertRule createSmartAlertRule(CreateSmartAlertRequest request) {
        // Use ML to suggest optimal thresholds
        ThresholdRecommendations recommendations = mlService.generateThresholdRecommendations(
            request.getTenantId(),
            request.getKey(),
            request.getMetricType(),
            Duration.ofDays(30)
        );

        AlertCondition condition;

        switch (request.getAlertType()) {
            case STATIC_THRESHOLD:
                condition = StaticThresholdCondition.builder()
                    .metric(request.getMetricType())
                    .threshold(request.getThreshold())
                    .operator(request.getOperator())
                    .build();
                break;

            case ADAPTIVE_THRESHOLD:
                condition = AdaptiveThresholdCondition.builder()
                    .metric(request.getMetricType())
                    .baselineWindow(Duration.ofDays(7))
                    .sensitivityLevel(request.getSensitivityLevel())
                    .seasonalAdjustment(recommendations.isSeasonalityDetected())
                    .build();
                break;

            case RATE_OF_CHANGE:
                condition = RateOfChangeCondition.builder()
                    .metric(request.getMetricType())
                    .changeWindow(Duration.ofMinutes(5))
                    .changeThreshold(request.getChangeThreshold())
                    .build();
                break;

            case PREDICTIVE:
                condition = PredictiveCondition.builder()
                    .metric(request.getMetricType())
                    .forecastHorizon(Duration.ofMinutes(15))
                    .confidenceLevel(0.95)
                    .thresholdType(request.getPredictiveThresholdType())
                    .build();
                break;

            default:
                throw new UnsupportedAlertTypeException(request.getAlertType());
        }

        AlertRule rule = AlertRule.builder()
            .id(UUID.randomUUID().toString())
            .name(request.getName())
            .description(request.getDescription())
            .tenantId(request.getTenantId())
            .key(request.getKey())
            .condition(condition)
            .severity(request.getSeverity())
            .cooldownPeriod(request.getCooldownPeriod())
            .notificationChannels(request.getNotificationChannels())
            .enabled(true)
            .createdAt(Instant.now())
            .createdBy(getCurrentUser())
            .build();

        return alertRuleRepository.save(rule);
    }
