        FeatureVector features = extractFeatures(request.getCurrentEvent(), historicalData);

        // Multiple detection algorithms
        List<AnomalyScore> scores = new ArrayList<>();

        // Isolation Forest (unsupervised)
        scores.add(isolationForest.calculateAnomalyScore(features));

        // LSTM-based time series anomaly detection
        scores.add(lstmModel.calculateAnomalyScore(features, historicalData));

        // Statistical anomaly detection
        scores.add(statisticalAnomalyDetection(features, historicalData));

        // Seasonal decomposition
        scores.add(seasonalDecomposer.detectSeasonalAnomalies(features, historicalData));

        // Ensemble scoring
        AnomalyScore ensembleScore = combineAnomalyScores(scores);

        // Determine if anomalous
        boolean isAnomalous = ensembleScore.getScore() > getAnomalyThreshold(request.getTenantId());

        if (isAnomalous) {
            return AnomalyDetectionResult.builder()
                .anomalous(true)
                .score(ensembleScore.getScore())
                .confidence(ensembleScore.getConfidence())
                .anomalyType(determineAnomalyType(scores))
                .severity(determineSeverity(ensembleScore))
                .description(generateAnomalyDescription(ensembleScore, scores))
                .recommendations(generateRecommendations(ensembleScore, request))
                .metadata(Map.of(
                    "individual_scores", scores,
                    "feature_importance", features.getImportanceScores(),
                    "historical_baseline", calculateBaseline(historicalData)
                ))
                .build();
        }

        return AnomalyDetectionResult.normal(ensembleScore.getScore());
    }
}
