#### **3. Alert Rule Configuration**
```java
// Smart alert rule builder
@Component
public class SmartAlertRuleBuilder {

    public AlertRule buildAdaptiveThresholdRule(String tenantId, String key, String metric) {
        // Analyze historical data to determine optimal thresholds
        HistoricalAnalysis analysis = analyzeHistoricalData(tenantId, key, metric, Duration.ofDays(30));

        // Calculate adaptive thresholds based on statistical analysis
        double mean = analysis.getMean();
        double stdDev = analysis.getStandardDeviation();
        double upperThreshold = mean + (2.5 * stdDev); // 2.5 sigma
        double lowerThreshold = Math.max(0, mean - (2.5 * stdDev));

        // Detect seasonality
        boolean hasSeasonality = analysis.getSeasonalityScore() > 0.7;

        AdaptiveThresholdCondition condition = AdaptiveThresholdCondition.builder()
            .metric(metric)
            .baselineWindow(Duration.ofDays(7))
            .upperThreshold(upperThreshold)
            .lowerThreshold(lowerThreshold)
            .seasonalAdjustment(hasSeasonality)
            .confidenceLevel(0.95)
            .build();

        return AlertRule.builder()
            .name(String.format("Adaptive %s Alert - %s", metric, key))
            .tenantId(tenantId)
            .key(key)
            .condition(condition)
            .severity(AlertSeverity.WARNING)
            .cooldownPeriod(Duration.ofMinutes(15))
            .build();
    }

    public AlertRule buildPredictiveAlert(String tenantId, String key, String metric) {
        // Use ML model to predict future values
        ForecastModel model = getForecastModel(tenantId, key, metric);

        PredictiveCondition condition = PredictiveCondition.builder()
            .metric(metric)
            .model(model)
            .forecastHorizon(Duration.ofMinutes(15))
            .confidenceLevel(0.95)
            .thresholdType(PredictiveThresholdType.CAPACITY_EXHAUSTION)
            .build();

        return AlertRule.builder()
            .name(String.format("Predictive %s Alert - %s", metric, key))
            .tenantId(tenantId)
            .key(key)
            .condition(condition)
            .severity(AlertSeverity.CRITICAL)
            .cooldownPeriod(Duration.ofMinutes(5))
            .build();
    }
}
